/// <summary>
/// Extends SysOperationServiceBase class
/// </summary>
final class AVACRLLimitExpiredService extends SysOperationServiceBase
{

}

Method.Source:
/// <summary>
/// startOperation method
/// </summary>
public void startOperation()
{
    System.Exception ex;
    #OCCRetryCount

    try
    {
        this.processOperation();
    }

    catch (Exception::Deadlock)
    {
        retry;
    }

    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }

    catch (Exception::Error)
    {
        error("@NDX:NXAErrorOccured");
        retry;
    }

    catch (Exception::CLRError)
    {
        ex = ClrInterop::getLastException();

        if (ex != null)
        {
            ex = ex.get_InnerException();
            if (ex != null)
            {
                error("@NDX:NXAErrorOccured");
            }
        }

        retry;
    }
}

/// <summary>
/// processOperation method
/// </summary>
private void processOperation()
{
    CustTable       custTable;

    while select forupdate custTable where custTable.CreditMax 
                              && (custTable.CredManCreditLimitExpiryDate != dateNull()
                              && custTable.CredManCreditLimitExpiryDate < DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()))
    {
        ttsbegin;
        custTable.CreditMax = 0;
        custTable.update();
        ttscommit;
    }
}
